using Pharaoh.Engine.ReverseEngineering;

namespace Pharaoh.Engine.Rendering;

/// <summary>
/// Exact 16-byte terrain-context records used by Pharaoh.exe. Bytes 0..7
/// describe N, NE, E, SE, S, SW, W, NW (2 = don't care), bytes 8..11 are
/// orientation offsets, and bytes 13..14 implement the original frame cycle.
/// </summary>
internal sealed class LegacyTerrainImageContext
{
    private const int RecordSize = 16;
    private readonly byte[] records;
    private readonly byte[] currentItems;
    private static readonly System.Collections.Concurrent.ConcurrentDictionary<string,byte[]> templates=[];

    private LegacyTerrainImageContext(string hex, int count)
    {
        records = templates.GetOrAdd(hex,static value=>Convert.FromHexString(value));
        if (records.Length != count * RecordSize)
            throw new InvalidDataException("Invalid legacy terrain-context table length.");
        currentItems = new byte[count];
        Reset();
    }

    [OriginalAddress(0x00484EE0,"Reset context cycling bytes before each deep-water lookup")]
    public void Reset()
    {for(int i=0;i<currentItems.Length;i++)currentItems[i]=records[i*RecordSize+14];}

    public static LegacyTerrainImageContext Water() => new(WaterHex, 48);
    [OriginalAddress(0x00484EE0, "FUN_00484ee0")]
    public static LegacyTerrainImageContext DeepWater() => new(DeepWaterHex, 26);
    public static LegacyTerrainImageContext Floodplain() => new(FloodplainHex, 24);
    public static LegacyTerrainImageContext FloodplainWaterSouth() => new(FloodplainWaterSouthHex, 24);
    public static LegacyTerrainImageContext DirtRoad() => new(DirtRoadHex, 17);
    public static LegacyTerrainImageContext PavedRoad() => new(PavedRoadHex, 48);

    public readonly record struct Selection(int OrientationOffset, int Variant, int CanalOffset)
    {
        public int LinearOffset => OrientationOffset + Variant;
    }

    public bool TryResolve(ReadOnlySpan<byte> neighbors, int orientationIndex, out int imageOffset)
    {
        bool matched = TryResolveSelection(neighbors, orientationIndex, out Selection selection);
        imageOffset = selection.LinearOffset;
        return matched;
    }

    public bool TryResolveSelection(
        ReadOnlySpan<byte> neighbors,
        int orientationIndex,
        out Selection selection)
        => TryResolveSelection(neighbors, orientationIndex, randomValue: -1, reverse: false, out selection);

    /// <summary>Mirrors the forward/reverse random-selection modes of FUN_00484BE0.</summary>
    public bool TryResolveRandomSelection(
        ReadOnlySpan<byte> neighbors,
        int orientationIndex,
        int randomValue,
        bool reverse,
        out Selection selection)
        => TryResolveSelection(neighbors, orientationIndex, randomValue, reverse, out selection);

    [OriginalAddress(0x00484BE0, "FUN_00484be0")]
    private bool TryResolveSelection(
        ReadOnlySpan<byte> neighbors,
        int orientationIndex,
        int randomValue,
        bool reverse,
        out Selection selection)
    {
        if (neighbors.Length != 8)
            throw new ArgumentException("A terrain context requires eight neighbors.", nameof(neighbors));
        if ((uint)orientationIndex >= 4)
            throw new ArgumentOutOfRangeException(nameof(orientationIndex));

        for (int scan = 0; scan < currentItems.Length; scan++)
        {
            int record = reverse ? currentItems.Length - 1 - scan : scan;
            int start = record * RecordSize;
            bool matches = true;
            for (int direction = 0; direction < 8; direction++)
            {
                byte expected = records[start + direction];
                if (expected != 2 && expected != neighbors[direction])
                {
                    matches = false;
                    break;
                }
            }
            if (!matches)
                continue;

            byte maximum = records[start + 13];
            bool useRandom = reverse ? randomValue != 0 : randomValue >= 0;
            byte item;
            if (useRandom)
            {
                item = maximum == 0 ? (byte)0 : (byte)(randomValue % maximum);
            }
            else
            {
                item = (byte)(currentItems[record] + 1);
                if (maximum == 0 || item >= maximum)
                    item = 0;
            }
            currentItems[record] = item;
            selection = new Selection(
                records[start + 8 + orientationIndex], item, records[start + 12]);
            return true;
        }

        selection = default;
        return false;
    }

    // Dumps from the verified GOG Pharaoh.exe:
    // water 005CA658 (48 records), deep water 005CBFB8 (26 records),
    // floodplain 005CAC58. FUN_00484D70 selects one of eight 24-record
    // sections from the cardinal WATER mask. Sections 0..4, 6 and 7 are
    // byte-identical; section 5 is the distinct south/south-west water case.
    private const string WaterHex = "";
    private const string DeepWaterHex = "";
    private const string FloodplainHex = "";
    private const string FloodplainWaterSouthHex = "";
    // Exact 17-record table at 0x005CC268, selected by Pharaoh.exe
    // FUN_0047B670 for ordinary low-desirability roads. Its image base is
    // terrain group 33 + 49; group 33 + 0 is the paved-road family.
    private const string DirtRoadHex = "";
    // Exact 48-record paved-road table at 0x005CC378.
    private const string PavedRoadHex = "";
}
